    tapa::streams<WORD, 2, BU_BUF_FIFO_DEPTH> fwd_BU_to_polyBuf_L0_4("fwd_BU_to_polyBuf_L0_4_stream");
    tapa::streams<WORD, 2, BU_BUF_FIFO_DEPTH> fwd_BU_to_polyBuf_L0_5("fwd_BU_to_polyBuf_L0_5_stream");
