        .invoke(BufModule_wiFW_5, polyLoad_to_polyBuf_L0_G0_2[1], polyLoad_to_polyBuf_L0_G0_3[1], fwd_BU_to_polyBuf_L0_5, inv_BU_to_polyBuf_L0_5, fwd_polyBuf_to_BU_L0_5, inv_polyBuf_to_BU_L0_5, polyBuf_to_polyStore_L0_G0_3[1], polyBuf_to_polyStore_L0_G0_2[1], direction, iter, 5)
        .invoke(BufModule_woFW_6, polyLoad_to_polyBuf_L0_G0_3[0], fwd_BU_to_polyBuf_L0_6, inv_BU_to_polyBuf_L0_6, fwd_polyBuf_to_BU_L0_6, inv_polyBuf_to_BU_L0_6, polyBuf_to_polyStore_L0_G0_3[0], direction, iter, 6)
        .invoke(BufModule_woFW_7, polyLoad_to_polyBuf_L0_G0_3[1], fwd_BU_to_polyBuf_L0_7, inv_BU_to_polyBuf_L0_7, fwd_polyBuf_to_BU_L0_7, inv_polyBuf_to_BU_L0_7, polyBuf_to_polyStore_L0_G0_3[1], direction, iter, 7)

        //BU tasks
        .invoke(BU, fwd_polyBuf_to_BU_L0_0[0], fwd_polyBuf_to_BU_L0_4[0], inv_polyBuf_to_BU_L0_0, tfBuf_to_BU_L0_0[0], fwd_BU_to_polyBuf_L0_0, inv_BU_to_polyBuf_L0_0[0], inv_BU_to_polyBuf_L0_4[0], q0, twoInverse0, factor0, direction, iter, 0)
