        .invoke(BU, fwd_polyBuf_to_BU_L0_1[0], fwd_polyBuf_to_BU_L0_5[0], inv_polyBuf_to_BU_L0_2, tfBuf_to_BU_L0_2[0], fwd_BU_to_polyBuf_L0_2, inv_BU_to_polyBuf_L0_1[0], inv_BU_to_polyBuf_L0_5[0], q0, twoInverse0, factor0, direction, iter, 2)
        .invoke(BU, fwd_polyBuf_to_BU_L0_1[1], fwd_polyBuf_to_BU_L0_5[1], inv_polyBuf_to_BU_L0_3, tfBuf_to_BU_L0_3[0], fwd_BU_to_polyBuf_L0_3, inv_BU_to_polyBuf_L0_1[1], inv_BU_to_polyBuf_L0_5[1], q0, twoInverse0, factor0, direction, iter, 3)
        .invoke(BU, fwd_polyBuf_to_BU_L0_2[0], fwd_polyBuf_to_BU_L0_6[0], inv_polyBuf_to_BU_L0_4, tfBuf_to_BU_L0_0[1], fwd_BU_to_polyBuf_L0_4, inv_BU_to_polyBuf_L0_2[0], inv_BU_to_polyBuf_L0_6[0], q0, twoInverse0, factor0, direction, iter, 4)
        .invoke(BU, fwd_polyBuf_to_BU_L0_2[1], fwd_polyBuf_to_BU_L0_6[1], inv_polyBuf_to_BU_L0_5, tfBuf_to_BU_L0_1[1], fwd_BU_to_polyBuf_L0_5, inv_BU_to_polyBuf_L0_2[1], inv_BU_to_polyBuf_L0_6[1], q0, twoInverse0, factor0, direction, iter, 5)
