template<typename T, int DEPTH = 2>
class tapa_stream {
public:
    std::queue<T> data;
    std::string name;

    tapa_stream() {}
    tapa_stream(const char* n) : name(n) {}

    void write(const T& val) { data.push(val); }
    T read() { T val = data.front(); data.pop(); return val; }
    bool empty() const { return data.empty(); }
    bool try_read(T& val) { 
        if (empty()) return false; 
        val = read(); 
        return true; 
    }
    bool try_write(const T& val) {
        if (data.size() >= DEPTH) return false;
        write(val);
        return true;
    }
};

