    std::queue<T> write_data;
    std::queue<uint64_t> read_addr;
    std::queue<uint64_t> write_addr;
    std::queue<uint8_t> write_resp;

    bool read_addr.try_write(uint64_t addr) { read_addr.push(addr); return true; }
    bool write_addr.try_write(uint64_t addr) { write_addr.push(addr); return true; }
    bool write_data.try_write(const T& data) { write_data.push(data); return true; }
