            __uint128_t s = (__uint128_t)data[i] + o.data[i] + c;
            r.data[i] = (uint64_t)s;
            c = (uint64_t)(s >> 64);
        }
        return r;
    }

    ap_uint operator-(const ap_uint& o) const {
        ap_uint r;
        uint64_t b = 0;
        for(int i = 0; i < words; i++) {
            __uint128_t d = (__uint128_t)data[i] - o.data[i] - b;
            r.data[i] = (uint64_t)d;
            b = (d >> 127) ? 1 : 0;
        }
        return r;
    }

