        ap_uint r;
        for(int i = 0; i < words; i++) r.data[i] = 0;
        for(int i = 0; i < words; i++) {
            uint64_t carry = 0;
            for(int j = 0; j < words - i; j++) {
                __uint128_t prod = (__uint128_t)data[i] * o.data[j] + r.data[i+j] + carry;
                r.data[i+j] = (uint64_t)prod;
                carry = (uint64_t)(prod >> 64);
            }
        }
        return r;
    }

    ap_uint operator<<(int s) const {
        ap_uint r;
        if (s <= 0) return *this;
        for(int i = 0; i < words; i++) r.data[i] = 0;
